#include "overrides.h"
#include "override_data.h"   // generated by tools/embed_overrides.py: kEmbeddedOverrides (assets/overrides/)
#include "../game/map.h"     // userDataPath
#include <algorithm>
#include <cctype>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <map>
#include <mutex>

namespace fs = std::filesystem;

namespace {
bool g_useUser = true, g_scanned = false;
std::mutex g_mu;
std::string g_userRoot;
std::map<std::string, fs::path> g_user;   // lower-case relative path -> file

std::string lower(std::string s) { for (char& c : s) c = (char)std::tolower((unsigned char)c); std::replace(s.begin(), s.end(), '\\', '/'); return s; }

void scan() {
    std::lock_guard<std::mutex> l(g_mu);
    if (g_scanned) return;
    g_scanned = true;
    g_user.clear();
    {
        if (!g_useUser) return;
        g_userRoot = userDataPath("overrides");
        std::error_code ec;
        fs::path root = fs::u8path(g_userRoot);
        if (!fs::is_directory(root, ec)) return;   // the usual case: one stat, nothing else
        for (auto it = fs::recursive_directory_iterator(root, ec); !ec && it != fs::recursive_directory_iterator(); it.increment(ec))
            if (it->is_regular_file(ec)) g_user[lower(fs::relative(it->path(), root, ec).generic_u8string())] = it->path();
    }
}

bool readFile(const fs::path& p, std::vector<uint8_t>& out) {
    std::ifstream f(p, std::ios::binary);
    if (!f) return false;
    f.seekg(0, std::ios::end);
    std::streamoff n = f.tellg();
    if (n < 0 || n > (256 << 20)) return false;
    f.seekg(0);
    out.resize((size_t)n);
    return n == 0 || (bool)f.read((char*)out.data(), n);
}

const EmbeddedOverride* embedded(const std::string& key) {
    for (const EmbeddedOverride* e = kEmbeddedOverrides; e->path; e++)
        if (lower(e->path) == key) return e;
    return nullptr;
}
} // namespace

namespace overrides {
void useUserFolder(bool on) { std::lock_guard<std::mutex> l(g_mu); g_useUser = on; g_scanned = false; }

bool any() {
    scan();
    return kEmbeddedOverrides[0].path || !g_user.empty();
}

bool find(const std::string& base, std::initializer_list<const char*> exts, std::vector<uint8_t>& out, std::string* matched, std::string* where) {
    if (!any()) return false;
    std::string b = lower(base);
    for (int pass = 0; pass < 2; pass++)   // yours first, then the shipped ones
        for (const char* ext : exts) {
            std::string key = b + lower(ext);
            if (pass == 0) {
                auto it = g_user.find(key);
                if (it == g_user.end() || !readFile(it->second, out)) continue;
                if (where) *where = "user";
            } else {
                const EmbeddedOverride* e = embedded(key);
                if (!e) continue;
                out.assign(e->data, e->data + e->size);
                if (where) *where = "shipped";
            }
            if (matched) *matched = key;
            return true;
        }
    return false;
}

bool readRelative(const std::string& path, std::vector<uint8_t>& out) {
    if (!any()) return false;
    std::string key = lower(path);
    auto it = g_user.find(key);
    if (it != g_user.end() && readFile(it->second, out)) return true;
    if (const EmbeddedOverride* e = embedded(key)) { out.assign(e->data, e->data + e->size); return true; }
    return false;
}

std::vector<std::string> list() {
    scan();
    std::vector<std::string> v;
    for (const EmbeddedOverride* e = kEmbeddedOverrides; e->path; e++) v.push_back("shipped:" + lower(e->path));
    for (auto& kv : g_user) v.push_back("user:" + kv.first);
    return v;
}
} // namespace overrides
